import fs from 'node:fs';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
const [repo,label]=process.argv.slice(2);
const {PNG}=await import(pathToFileURL(`${repo}/packages/capture-kit/src/png.ts`));
const {encodePngAsync,retainPngWorker,terminatePngWorker}=await import(pathToFileURL(`${repo}/packages/capture-kit/src/png-worker-client.ts`));
const failures=[];const release=retainPngWorker(r=>failures.push(r));
const outputs=[];
try{
 for(const file of [new URL('./baseline-0.png',import.meta.url).pathname,'/private/tmp/e2e-ios-bench/direct/screenshots/001-bench-0.png']){
  const png=PNG.sync.read(fs.readFileSync(file)),samples=[];
  for(let i=0;i<22;i++){
   const started=performance.now();
   const bytes=await encodePngAsync(png);
   const ms=performance.now()-started;
   const actual=PNG.sync.read(bytes);
   assert.equal(actual.width,png.width);assert.equal(actual.height,png.height);assert.deepEqual(actual.data,png.data);
   assert.deepEqual(failures,[],'worker unavailable');
   if(i>=2)samples.push({ms,bytes:bytes.length});
  }
  outputs.push({source:file,width:png.width,height:png.height,verifiedPixels:true,samples});
 }
 fs.writeFileSync(new URL(`./png-${label}.json`,import.meta.url),JSON.stringify(outputs,null,2));
 for(const o of outputs){const values=o.samples.map(s=>s.ms).sort((a,b)=>a-b);console.log(label,o.width,o.height,(values[9]+values[10])/2)}
}finally{await release();await terminatePngWorker()}

