import fs from 'node:fs';
import assert from 'node:assert/strict';
import zlib from 'node:zlib';
import {screenshotIos} from '../../packages/platform-apple/src/core/screenshot.ts';
import {PNG} from '../../packages/capture-kit/src/png.ts';
import {retainPngWorker,terminatePngWorker} from '../../packages/capture-kit/src/png-worker-client.ts';
const device={platform:'apple',id:'BC54AC11-CD86-4C10-8C4E-5101C773FFEB',name:'iPhone 17 Pro',kind:'simulator',booted:true};
const unavailable=[],release=retainPngWorker(reason=>unavailable.push(reason)),checks=[];
function filters(bytes,width,height){
 const parts=[];
 for(let offset=8;offset+12<=bytes.length;){
  const length=bytes.readUInt32BE(offset),type=bytes.toString('ascii',offset+4,offset+8);
  if(type==='IDAT')parts.push(bytes.subarray(offset+8,offset+8+length));offset+=length+12;
 }
 const raw=zlib.inflateSync(Buffer.concat(parts));
 return Array.from({length:height},(_,row)=>raw[row*(width*4+1)]);
}
try{
 for(const [density,width,height] of [[1,402,874],[1.25,503,1093],[3,1206,2622]]){
  const file=new URL(`./live-png-${density}.png`,import.meta.url).pathname;
  const facts=await screenshotIos(device,file,{pixelDensity:density,skipIosSimulatorBootCheck:true});
  const bytes=fs.readFileSync(file),image=PNG.sync.read(bytes);
  assert.equal(image.width,width);assert.equal(image.height,height);
  if(density!==3){assert.equal(bytes[25],6);assert(filters(bytes,width,height).every(f=>f===0),'optimized encoder did not produce None-filter rows')}
  assert.deepEqual(unavailable,[],'PNG worker unavailable');
  checks.push({density,width,height,bytes:bytes.length,facts,ok:true});
  console.log('live screenshot',density,width,height,'OK');
 }
 fs.writeFileSync(new URL('./live-png-check.json',import.meta.url),JSON.stringify(checks,null,2));
}finally{await release();await terminatePngWorker()}

