 const start=performance.now();const p=spawnSync('/Users/michal/.t3/userdata/device/bin/agent-device',[...args,...flags],{encoding:'utf8',timeout:120000});
 const ms=performance.now()-start;let result;try{result=JSON.parse(p.stdout)}catch{throw Error(`Invalid ${args[0]} JSON; exit ${p.status}`)}
