rebaseComparison.daemonBenchmarkScript:
import fs from 'node:fs';
import net from 'node:net';
import childProcess from 'node:child_process';
import {syncBuiltinESMExports} from 'node:module';
const probes=[];
for (const method of ['spawn','spawnSync']) {
  const original=childProcess[method];
  childProcess[method]=function(command,args,...rest) {
    const start=performance.now();
    const result=original.call(this,command,args,...rest);
    const record=()=>probes.push({method,command,args:command==='ps'?args:undefined,ms:performance.now()-start});
    if(method==='spawnSync')record();else result.once('close',record);
    return result;
  };
}
syncBuiltinESMExports();
const [repo,label]=process.argv.slice(2);
const {pathToFileURL}=await import('node:url');
const {createAgentDeviceClient}=await import(pathToFileURL(`${repo}/dist/src/index.js`));
const stateDir=`/private/tmp/agent-device-rebase-raw-${label}`;
const client=createAgentDeviceClient({stateDir,session:'speed',debug:false});
await client.sessions.list();
const info=JSON.parse(fs.readFileSync(`${stateDir}/daemon.json`,'utf8'));
const result={sdk:[],raw:[],probes};
function raw() {
 return new Promise((resolve,reject)=>{
  let data='';
  const socket=net.createConnection({host:'127.0.0.1',port:info.port},()=>socket.write(JSON.stringify({token:info.token,command:'session_list',positionals:[],session:'speed',meta:{requestId:crypto.randomUUID()}})+'\n'));
  socket.setTimeout(5000,()=>socket.destroy(Error('timeout')));
  socket.on('data',chunk=>{data+=chunk;if(data.includes('\n')){socket.destroy();const response=JSON.parse(data.split('\n')[0]);response.ok?resolve(response):reject(Error(JSON.stringify(response)));}});
  socket.on('error',reject);
 });
}
for(let i=0;i<110;i++) {
 for(const [name,fn] of [['sdk',()=>client.sessions.list()],['raw',raw]]) {
  const start=performance.now();await fn();if(i>=10)result[name].push(performance.now()-start);
 }
}
fs.writeFileSync(new URL(`./daemon-${label}.json`,import.meta.url),JSON.stringify(result,null,2));
for(const key of ['sdk','raw']) {const sorted=result[key].toSorted((a,b)=>a-b);console.log(key,{p50:(sorted[49]+sorted[50])/2,p95:sorted[94],min:sorted[0],max:sorted.at(-1)});}
console.log('probe counts',Object.fromEntries([...new Set(probes.map(p=>p.command))].map(c=>[c,probes.filter(p=>p.command===c).length])));

const stopped=childProcess.spawnSync(process.execPath,[`${repo}/bin/agent-device.mjs`,'daemon','stop','--state-dir',stateDir],{cwd:repo,encoding:'utf8',timeout:90000});if(stopped.status!==0)throw Error('Own benchmark daemon stop failed');
